13	// === 전역 채널 (클라이언트 ↔ 서버 통신) ===
14	let g_request_channel: concurrent.Channel;
15	let g_response_channel: concurrent.Channel;
16	let g_server_running: bool = false;
17	
18	// === 서버 초기화 ===
19	fn init_bns_server() {
20	    g_request_channel = concurrent.chan_new(64);
21	    g_response_channel = concurrent.chan_new(64);
22	    g_server_running = true;
23	    bns_broadcast.broadcast_init();
24	}
25	
26	// === 서버 루프 (메인 진입점) ===
27	fn bns_server_loop() {
28	    init_bns_server();
29	
30	    println("🚀 BNS Server started");
31	    println("Listening on localhost:28080 (in-process Channel)");
32	    println("");
33	    println("Endpoints:");
34	    println("  GET  /api/status      - 프로젝트 상태");
35	    println("  GET  /api/gogs        - Gogs 커밋");
36	    println("  GET  /api/feed        - Server-Sent Events");
37	    println("  GET  /api/db          - DB 상태");
38	    println("  POST /webhook/gogs    - Gogs Webhook");
39	    println("");
40	
41	    let request_count = 0;
42	
43	    // 단순 요청 처리 루프 (협동 스케줄링)
44	    loop {
45	        // 요청 수신 (논블로킹)
46	        let (request_str, ok) = g_request_channel.chan_recv();
47	
48	        if ok && len(request_str) > 0 {
49	            request_count = request_count + 1;
50	
51	            // HTTP 요청 파싱
52	            let req = bns_http.parse_http_request(request_str);
53	
54	            println("[" + to_string(request_count) + "] " + req.method + " " + req.path);
55	
56	            // 라우팅: 핸들러 선택
57	            let response: bns_models.HttpResponse;
58	
59	            if req.method == "POST" && req.path == "/webhook/gogs" {
60	                response = bns_webhook.handle_webhook(req);
61	            } else {
62	                response = bns_handlers.handle_request(req);
63	            }
64	
65	            // HTTP 응답 형식화
66	            let response_str = bns_http.format_http_response(response);
67	
68	            // 응답 전송
69	            g_response_channel.chan_send(response_str);
70	        }
71	
72	        // 협동 양보 (다른 작업에 CPU 할당)
73	        if request_count % 10 == 0 {
74	            // 간단한 yield 시뮬레이션 (실제 구현에서는 sys_yield 필요)
75	        }
76	    }
77	}
