79	// === 클라이언트 API: 요청 전송 ===
80	fn send_http_request(method: string, path: string, body: string) -> string {
81	    // 요청 구성 (간단한 HTTP 요청)
82	    let request = method + " " + path + " HTTP/1.1\r\n";
83	    request = request + "Host: localhost:28080\r\n";
84	    request = request + "Content-Type: application/json\r\n";
85	
86	    if len(body) > 0 {
87	        request = request + "Content-Length: " + to_string(len(body)) + "\r\n";
88	    }
89	
90	    request = request + "\r\n";
91	    if len(body) > 0 {
92	        request = request + body;
93	    }
94	
95	    // 요청 전송
96	    g_request_channel.chan_send(request);
97	
98	    // 응답 수신 (폴링, max 100 tick)
99	    let i = 0;
100	    let response = "";
101	
102	    for i = 0; i < 100; i = i + 1 {
103	        let (resp, ok) = g_response_channel.chan_recv();
104	
105	        if ok && len(resp) > 0 {
106	            response = resp;
107	            break;
108	        }
109	
110	        // 짧은 대기 (실제로는 nanosleep 필요)
111	    }
112	
113	    return response;
114	}
