152	fn to_string(n: i32) -> string {
153	    if n == 0 {
154	        return "0";
155	    }
156	
157	    let negative = false;
158	    if n < 0 {
159	        negative = true;
160	        n = 0 - n;
161	    }
162	
163	    let result = "";
164	    let temp = n;
165	
166	    for temp > 0 {
167	        let digit = temp % 10;
168	        let ch = char_from_code(48 + digit);  // '0' = 48
169	        result = ch + result;
170	        temp = temp / 10;
171	    }
172	
173	    if negative {
174	        result = "-" + result;
175	    }
176	
177	    return result;
178	}
