166	    @inline
167	    func index_of(haystack: string, needle: string) -> i32 {
168	        let i = 0;
169	        let j = 0;
170	        let h_len = len(haystack);
171	        let n_len = len(needle);
172	
173	        if n_len == 0 || n_len > h_len {
174	            return -1;
175	        }
176	
177	        for i = 0; i <= h_len - n_len; i = i + 1 {
178	            let found = true;
179	            for j = 0; j < n_len; j = j + 1 {
180	                if char_at(haystack, i + j) != char_at(needle, j) {
181	                    found = false;
182	                    break;
183	                }
184	            }
185	            if found {
186	                return i;
187	            }
188	        }
189	
190	        return -1;
191	    }
192	
193	    @inline
194	    func substring(s: string, start: i32, end: i32) -> string {
195	        let result = "";
196	        let i = start;
197	
198	        for i = start; i < end; i = i + 1 {
199	            let ch = char_from_code(char_at(s, i));
200	            result = result + ch;
201	        }
202	
203	        return result;
204	    }
205	
206	    @inline
207	    func join_strings(parts: [string], sep: string) -> string {
208	        let result = "";
209	        let i = 0;
210	
211	        for i = 0; i < len(parts); i = i + 1 {
212	            if i > 0 {
213	                result = result + sep;
214	            }
215	            result = result + parts[i];
216	        }
217	
218	        return result;
219	    }
220	}
