4	// Gogs Webhook → 모든 SSE 구독자에 이벤트 전파
5	
6	module bns_broadcast {
7	    use concurrent;
8	
9	    // === 상수 ===
10	    const MAX_SUBSCRIBERS: i32 = 10;
11	    const MAX_EVENTS:      i32 = 256;
12	
13	    // === 전역 상태 ===
14	    let g_event_pool:         [string];      // 이벤트 JSON 저장소
15	    let g_event_count:        i32 = 0;       // 저장된 이벤트 수
16	    let g_latest_event_idx:   i32 = -1;      // 최신 이벤트 인덱스
17	
18	    // 구독자 채널 배열 (각 SSE 연결마다 1개)
19	    let g_subscriber_channels: [concurrent.Channel];
20	    let g_subscriber_count:    i32 = 0;
21	
22	    // === 초기화 ===
23	    func broadcast_init() {
24	        g_event_pool = make([string], MAX_EVENTS);
25	        g_subscriber_channels = make([concurrent.Channel], MAX_SUBSCRIBERS);
26	        g_event_count = 0;
27	        g_latest_event_idx = -1;
28	        g_subscriber_count = 0;
29	    }
30	
31	    // === 구독 (SSE 연결이 들어올 때) ===
32	    func broadcast_subscribe() -> (concurrent.Channel, i32) {
33	        if g_subscriber_count >= MAX_SUBSCRIBERS {
34	            // 구독자 수 초과
35	            let empty: concurrent.Channel;
36	            return (empty, -1);
37	        }
38	
39	        // 새 채널 생성 (capacity 64)
40	        let ch = concurrent.chan_new(64);
41	        g_subscriber_channels[g_subscriber_count] = ch;
42	        let sub_id = g_subscriber_count;
43	        g_subscriber_count = g_subscriber_count + 1;
44	
45	        return (ch, sub_id);
46	    }
47	
48	    // === 구독 해제 (SSE 연결 종료 시) ===
49	    func broadcast_unsubscribe(id: i32) {
50	        if id < 0 || id >= g_subscriber_count {
51	            return;
52	        }
53	
54	        // 채널 닫기
55	        g_subscriber_channels[id].chan_close();
56	
57	        // 구독자 수 감소
58	        g_subscriber_count = g_subscriber_count - 1;
59	    }
60	
61	    // === 이벤트 브로드캐스트 ===
62	    // Gogs webhook에서 호출: broadcast_event(json_string)
63	    func broadcast_event(event_json: string) {
64	        if g_event_count >= MAX_EVENTS {
65	            // 이벤트 풀 오버플로우 (순환 큐 패턴으로 개선 가능)
66	            return;
67	        }
68	
69	        // 1. 이벤트 풀에 저장
70	        let idx = g_event_count;
71	        g_event_pool[idx] = event_json;
72	        g_latest_event_idx = idx;
73	        g_event_count = g_event_count + 1;
74	
75	        // 2. 모든 구독자 채널에 인덱스 전송 (1→N 브로드캐스트)
76	        let i = 0;
77	        for i = 0; i < g_subscriber_count; i = i + 1 {
78	            let ch = g_subscriber_channels[i];
79	            ch.chan_send(idx as i64);  // i64로 인덱스 전송
80	        }
81	    }
82	
83	    // === 이벤트 조회 ===
84	    func broadcast_get_event(idx: i64) -> string {
85	        let idx_i32 = idx as i32;
86	
87	        if idx_i32 < 0 || idx_i32 >= g_event_count {
88	            return "";
89	        }
90	
91	        return g_event_pool[idx_i32];
92	    }
93	
94	    // === 최신 이벤트 조회 ===
95	    func broadcast_get_latest() -> string {
96	        if g_latest_event_idx < 0 {
97	            return "{}";  // 빈 이벤트
98	        }
99	
100	        return g_event_pool[g_latest_event_idx];
101	    }
102	
103	    // === 이벤트 통계 ===
104	    func broadcast_get_stats() -> string {
105	        let stats = "{";
106	        stats = stats + "\"event_count\": " + to_string(g_event_count) + ",";
107	        stats = stats + "\"subscriber_count\": " + to_string(g_subscriber_count) + ",";
108	        stats = stats + "\"max_subscribers\": " + to_string(MAX_SUBSCRIBERS);
109	        stats = stats + "}";
110	        return stats;
111	    }
112	
113	    // === 헬퍼: 정수를 문자열로 ===
114	    @inline
115	    func to_string(n: i32) -> string {
116	        if n == 0 {
117	            return "0";
118	        }
119	
120	        let negative = false;
121	        if n < 0 {
122	            negative = true;
123	            n = 0 - n;
124	        }
125	
126	        let result = "";
127	        let temp = n;
128	
129	        for temp > 0 {
130	            let digit = temp % 10;
131	            let ch = char_from_code(48 + digit);  // '0' = 48
132	            result = ch + result;
133	            temp = temp / 10;
134	        }
135	
136	        if negative {
137	            result = "-" + result;
138	        }
139	
140	        return result;
141	    }
142	}
