11	    // === Gogs Push 이벤트 판별 ===
12	    // 헤더 "X-Gogs-Event: push" 확인
13	    func is_push_event(headers: [string]) -> bool {
14	        let i = 0;
15	        for i = 0; i < len(headers); i = i + 1 {
16	            let header = headers[i];
17	
18	            // "X-Gogs-Event: push" 찾기
19	            if index_of(header, "X-Gogs-Event") >= 0 && index_of(header, "push") >= 0 {
20	                return true;
21	            }
