27	    // === JSON에서 문자열 값 추출 ===
28	    // 형식: "key": "value" → value 반환
29	    @inline
30	    func extract_json_string(json: string, key: string) -> string {
31	        let search = "\"" + key + "\": \"";
32	        let start_idx = index_of(json, search);
33	
34	        if start_idx < 0 {
35	            return "";
36	        }
37	
38	        let value_start = start_idx + len(search);
39	        let end_idx = index_of_from(json, "\"", value_start);
40	
41	        if end_idx < 0 {
42	            return "";
43	        }
44	
45	        return bns_http.substring(json, value_start, end_idx);
46	    }
