48	    // === Gogs Push Payload 파싱 ===
49	    // 입력: Gogs webhook JSON
50	    // 출력: GogsCommit 구조체
51	    func parse_gogs_payload(body: string) -> bns_models.GogsCommit {
52	        let commit: bns_models.GogsCommit;
53	
54	        // 저장소 이름 추출
55	        commit.repo = extract_json_string(body, "repository");
56	        if len(commit.repo) == 0 {
57	            commit.repo = "unknown";
58	        }
59	
60	        // commits 배열에서 첫 번째 커밋 추출
61	        // 간단한 파싱: "commits": [{"id": "...", "message": "..."}]
62	        let commits_idx = index_of(body, "\"commits\": [");
63	
64	        if commits_idx >= 0 {
65	            let commit_obj_start = commits_idx + len("\"commits\": [");
66	            let commit_obj_end = index_of_from(body, "}", commit_obj_start);
67	
68	            if commit_obj_end >= 0 {
69	                let commit_obj = bns_http.substring(body, commit_obj_start, commit_obj_end + 1);
70	
71	                // 커밋 해시 추출 (id)
72	                commit.hash = extract_json_string(commit_obj, "id");
73	                if len(commit.hash) > 7 {
74	                    commit.hash = bns_http.substring(commit.hash, 0, 7);  // 처음 7자리
75	                }
76	
77	                // 커밋 메시지 추출
78	                commit.message = extract_json_string(commit_obj, "message");
79	                if len(commit.message) == 0 {
80	                    commit.message = "unnamed commit";
81	                }
82	
83	                // 변경 파일 수 (estimates)
84	                commit.files_changed = count_field(commit_obj, "filename");
85	            }
86	        }
87	
88	        // ref에서 branch 추출 (refs/heads/master → master)
89	        let ref_str = extract_json_string(body, "ref");
90	        if index_of(ref_str, "refs/heads/") >= 0 {
91	            let branch_start = index_of(ref_str, "refs/heads/") + len("refs/heads/");
92	            commit.date = bns_http.substring(ref_str, branch_start, len(ref_str));
93	        } else {
94	            commit.date = "2026-03-29";  // 기본값
95	        }
96	
97	        return commit;
98	    }
