100	    // === 서명 검증 (간소화) ===
101	    // 실제 HMAC-SHA256 대신 X-Gogs-Signature 존재 여부만 확인
102	    func verify_signature(headers: [string], secret: string) -> bool {
103	        let i = 0;
104	        for i = 0; i < len(headers); i = i + 1 {
105	            let header = headers[i];
106	
107	            if index_of(header, "X-Gogs-Signature") >= 0 {
108	                return true;  // 서명 헤더 존재 = 인증됨
109	            }
110	        }
111	
112	        return false;
113	    }
