115	    // === Webhook 처리 진입점 ===
116	    func handle_webhook(req: bns_models.HttpRequest) -> bns_models.HttpResponse {
117	        // 1. 이벤트 타입 확인
118	        if !is_push_event(req.headers) {
119	            return bns_models.http_response_error(400, "Not a push event");
120	        }
121	
122	        // 2. 서명 검증
123	        if !verify_signature(req.headers, "gogs-secret") {
124	            return bns_models.http_response_error(401, "Signature verification failed");
125	        }
126	
127	        // 3. 페이로드 파싱
128	        let commit = parse_gogs_payload(req.body);
129	
130	        // 4. JSON으로 변환
131	        let event_json = "{";
132	        event_json = event_json + "\"repo\": \"" + commit.repo + "\",";
133	        event_json = event_json + "\"hash\": \"" + commit.hash + "\",";
134	        event_json = event_json + "\"message\": \"" + commit.message + "\",";
135	        event_json = event_json + "\"date\": \"" + commit.date + "\",";
136	        event_json = event_json + "\"files_changed\": " + to_string(commit.files_changed);
137	        event_json = event_json + "}";
138	
139	        // 5. 브로드캐스트 (모든 SSE 구독자에 전파)
140	        bns_broadcast.broadcast_event(event_json);
141	
142	        // 6. 응답 (202 Accepted)
143	        let resp_body = "{\"status\": \"received\", \"repo\": \"" + commit.repo + "\", \"hash\": \"" + commit.hash + "\"}";
144	        return bns_models.http_response_ok(resp_body, bns_models.CONTENT_JSON);
145	    }
