167	    @inline
168	    func index_of_from(haystack: string, needle: string, start: i32) -> i32 {
169	        let i = start;
170	        let j = 0;
171	        let h_len = len(haystack);
172	        let n_len = len(needle);
173	
174	        if n_len == 0 || n_len > h_len {
175	            return -1;
176	        }
177	
178	        for i = start; i <= h_len - n_len; i = i + 1 {
179	            let found = true;
180	            for j = 0; j < n_len; j = j + 1 {
181	                if char_at(haystack, i + j) != char_at(needle, j) {
182	                    found = false;
183	                    break;
184	                }
185	            }
186	            if found {
187	                return i;
188	            }
189	        }
190	
191	        return -1;
192	    }
