175	    // === 헬퍼: Phase 숫자 추출 ===
176	    @inline
177	    func extract_phase_number(line: string) -> i32 {
178	        // "Phase 11" 패턴 찾기
179	        let idx = index_of(line, "Phase ");
180	        if idx < 0 {
181	            return 1;  // 기본값
182	        }
183	
184	        let start = idx + 6;  // "Phase " 다음
185	        if start >= len(line) {
186	            return 1;
187	        }
188	
189	        // 숫자 2글자 추출
190	        let ch1 = char_at(line, start);
191	        let ch2 = 0;
192	        if start + 1 < len(line) {
193	            ch2 = char_at(line, start + 1);
194	        }
195	
196	        // ASCII: '0' = 48, '9' = 57
197	        if ch1 >= 48 && ch1 <= 57 {
198	            let phase = ch1 - 48;
199	            if ch2 >= 48 && ch2 <= 57 {
200	                phase = phase * 10 + (ch2 - 48);
201	            }
202	            return phase as i32;
203	        }
204	
205	        return 1;
206	    }
