208	    // === 헬퍼: 줄 수 추출 ===
209	    @inline
210	    func extract_line_count(line: string) -> i32 {
211	        // "22,439줄" 패턴 찾기
212	        let idx = index_of(line, "줄");
213	        if idx < 0 {
214	            return 0;
215	        }
216	
217	        // 숫자 부분 역추적
218	        let end = idx;
219	        let start = end - 1;
220	
221	        // 쉼표 제거하고 숫자만 추출
222	        for start = end - 1; start >= 0; start = start - 1 {
223	            let ch = char_at(line, start);
224	            if (ch < 48 || ch > 57) && ch != 44 {  // 44 = ','
225	                break;
226	            }
227	        }
228	
229	        start = start + 1;
230	        let num_str = bns_http.substring(line, start, end);
231	
232	        // 쉼표 제거
233	        let result = "";
234	        let i = 0;
235	        for i = 0; i < len(num_str); i = i + 1 {
236	            let ch = char_at(num_str, i);
237	            if ch != 44 {  // 쉼표 아님
238	                result = result + char_from_code(ch);
239	            }
240	        }
241	
242	        // 문자열을 숫자로 변환 (간단한 방식)
243	        return parse_int(result);
