267	    @inline
268	    func index_of(haystack: string, needle: string) -> i32 {
269	        let i = 0;
270	        let j = 0;
271	        let h_len = len(haystack);
272	        let n_len = len(needle);
273	
274	        if n_len == 0 || n_len > h_len {
275	            return -1;
276	        }
277	
278	        for i = 0; i <= h_len - n_len; i = i + 1 {
279	            let found = true;
280	            for j = 0; j < n_len; j = j + 1 {
281	                if char_at(haystack, i + j) != char_at(needle, j) {
282	                    found = false;
283	                    break;
284	                }
285	            }
286	            if found {
287	                return i;
288	            }
289	        }
290	
291	        return -1;
292	    }
