374	    @inline
375	    func to_string(n: i32) -> string {
376	        if n == 0 {
377	            return "0";
378	        }
379	
380	        let negative = false;
381	        if n < 0 {
382	            negative = true;
383	            n = 0 - n;
384	        }
385	
386	        let result = "";
387	        let temp = n;
388	
389	        for temp > 0 {
390	            let digit = temp % 10;
391	            let ch = char_from_code(48 + digit);
392	            result = ch + result;
393	            temp = temp / 10;
394	        }
395	
396	        if negative {
397	            result = "-" + result;
398	        }
399	
400	        return result;
401	    }
